    // Objective: Minimize score (Best Fit Decreasing / Best Fit with Lookahead logic)
    // post_residual: Lower is better (Best Fit).
    // penalty for creating a "fragment" (small residual that cannot fit average future items).

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Heavily favor tighter fits.
    // We add a non-linear cost for leaving too much space.
    score += (post_residual as f64).powf(1.2);

    // 2. Lookahead Integration: If the next item fits in the current post_residual, 
    // reward this bin to keep the next item "tucked in".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Fragmentation Penalty: If the post_residual is small but > 0, it's often wasted space.
    // Penalize residuals that are too small to fit most items (e.g., < 20).
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.5;
    }

    // 4. Global State: If we have many open bins, prioritize closing the gap in existing ones.
    if open_bins_count > 0 {
        score += (open_bins_count as f64) * 0.5;
    }

    // 5. New Bin Logic: If this is an empty bin (bin_residual == bin_capacity), 
    // only open it if the current fit is catastrophic (e.g., leaving a tiny gap in all existing bins).
    if bin_residual == bin_capacity {
        // High base cost to open a new bin, reduced by progress (late game, opening bins is safer).
        let new_bin_cost = 65.0 - (progress * 20.0);
        score = new_bin_cost;
    } else {
        // If it's a fitting bin but not the only one, slightly penalize if it's very empty 
        // to encourage packing items into bins that are already "half-full".
        if fitting_bins_count > 1 && bin_residual > (bin_capacity / 2) {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: Favor smaller post_residual (Best Fit principle)
    // We penalize the post_residual quadratically to avoid leaving small, unusable gaps.
    let mut score = post * post * 0.01;

    // Lookahead logic: If the next item fits into the current post_residual, 
    // heavily reward this bin to create a "perfect pair".
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 5.0;
    }

    // Progression logic: As the stream nears completion, reduce the penalty for 
    // opening new bins by rewarding a "tight" fit in a new bin relative to the mean.
    if bin_residual == bin_capacity {
        // This is a candidate for a new bin. 
        // We evaluate if opening a new bin is better than keeping high-residual bins.
        score += 50.0 - (progress * 20.0);
    } else {
        // If it's an existing bin, penalize bins that are significantly 
        // less efficient than the current mean residual.
        if (bin_residual as f64) > mean_residual {
            score += (bin_residual as f64 - mean_residual) * 0.5;
        }
    }

    // Constraint handling: If this is the last bin that can fit the item, 
    // provide a slight incentive to use it to prevent unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Non-linear coupling: Amplify the cost of large residuals as the stream progresses
    // to encourage consolidation in the final stages.
    score += (post * progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score (Best Fit Decreasing + Lookahead logic)
    // post_residual: Remaining space after placement.
    // We want to minimize post_residual (Best Fit), but penalize creating "dead space"
    // that cannot accommodate the next expected item or the average item.

    let mut score = post_residual as f64;

    // 1. Best Fit logic: punish larger post_residuals
    // The base score is already post_residual, which favors tight fits.

    // 2. Lookahead Penalty: If the post_residual is slightly too small for the next_item,
    // we penalize it heavily to encourage using a different bin that might leave
    // enough room for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        // Penalty for creating a "gap" that is useless for the immediate next step.
        score += 40.0;
