    // If this bin's post_residual is significantly better (lower) than the current average,
    // we reward it to solidify the tight packing.
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // 5. New Bin Logic (bin_residual == bin_capacity):
    // We only want to open a new bin if the existing options are very poor.
    if bin_residual == bin_capacity {
        // If we have fitting bins, opening a new one is usually a last resort.
        // We set a high threshold so that new bins are only opened if the score
        // of existing bins is worse than this constant.
        score = 65.0 - ((step_index as f64 / total_items as f64) * 10.0);
    }

    // 6. Last Chance logic:
    // If this is the only bin that can fit the item, we should prioritize it
    // regardless of the residual, unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
