            // Penalize leaving space smaller than the next item if we are mid-stream
            score += 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Reward bins that leave exactly enough space for the next item
            if post_residual < (next_item_size + 5) {
                score -= 10.0;
            }
        }
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), only choose it if the penalty 
    // for using existing bins is extremely high.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin, reduced by the number of currently open bins
        // to prevent fragmentation when many bins are already open.
        score = 55.0 - (open_bins_count as f64 * 0.5);
    } else {
        // 5. Fitting Bin Density: 
        // If this is the last bin that can fit the item, give it a significant priority boost
