pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual to fill bins tightly (Best Fit strategy),
    // but penalize small, unusable "dead spaces" (residual < 10) that cannot fit any item.
    // Also, apply pressure to keep open_bins_count low to avoid fragmentation.

    let mut score = post_residual as f64;

    // Penalty for creating a "sliver": if post_residual is > 0 but < 10,
    // it is likely unusable for future items (min size is 1).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead: If next_item_size exists and doesn't fit in the remaining space,
    // penalize the current placement if it makes the bin less likely to accept the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // New Bin Penalty: Heavily penalize opening a new bin unless necessary.
    // If bin_residual == bin_capacity, we are evaluating the cost of a new bin.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to encourage filling existing ones.
        score = 80.0 + (open_bins_count as f64 * 0.5);
    } else {
        // Reward keeping open_bins_count low:
        // If we have many open bins, prioritize filling the ones with the lowest residual
        // to consolidate space.
        score += (open_bins_count as f64 * 2.0);
    }

    // If this bin is the last chance for this item, reduce the score to force the fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that cannot fit common items).
    // If post_residual is small but > 0, it's often worse than 0.
    if post_residual > 0 && post_residual < 10 {
