    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // Dynamic thresholding for new bins:
    // As progress approaches 1.0, we become more aggressive in opening new bins to avoid 
    // fragmenting existing bins that could have accommodated future items.
    if is_new_bin {
        // Base cost for new bin is high, scaled by the difficulty of the pack.
        // We reduce the penalty for opening a new bin as the stream progresses.
        let new_bin_penalty = 35.0 * (1.0 - progress.powf(0.5));
        score += new_bin_penalty;
    } else {
        // If this bin is the only one that fits, incentivize it to prevent premature new bin opening.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Penalize deviations from the mean residual to keep bin levels balanced.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize score.
    // Archetype: Harmonic/Residual packing.
    // 1. Penalty for leaving small, unusable gaps (1-9) which are hard to fill.
    // 2. Reward fitting next_item_size into post_residual.
    // 3. Weight against opening new bins unless fitting_bins_count is low or fit is perfect.

    let mut score = post_residual as f64;

    // Penalty for creating "sliver" residuals (1..9), which are highly inefficient.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        // Reward tighter fits for the lookahead item.
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless there are no other good options (fitting_bins_count is small).
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we have many fitting bins, don't open a new one.
        score += fitting_bins_count as f64 * 15.0;
    } else {
        // For existing bins, favor those closer to the mean_residual to keep bin distribution uniform.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Progress scaling: As the stream nears completion, become more aggressive about closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that are likely to be "stranded" (too small for most items).
    // If post_residual is < 10, it is effectively dead space since min item size is likely small, 
    // but we want to avoid creating gaps that are difficult to fill.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    // 2. Open Bin Pressure: Penalize opening new bins when there are many open bins already.
    // If this is a new bin (bin_residual == bin_capacity), increase score based on current open count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 3. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Global Density Optimization: Favor bins that align with the mean residual of the set.
    // This helps keep bins packed somewhat uniformly to allow future items a better chance at fitting.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space": small residuals that are unlikely to fit future items.
    // If post_residual is small but > 0, it's often worse than having 0 residual.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
