    // 3. Efficiency heuristic: Favor bins that stay close to the current mean_residual.
    // This encourages leveling the bins rather than creating one very full and one very empty bin.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 4. New Bin Logic: Discourage opening a new bin unless the existing fits are extremely poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty for opening a new bin if we have plenty of open bins that could fit.
        score += 50.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward using existing bins.
        score -= 10.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, be more conservative.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: prioritize tighter fits (Best Fit approach)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin unnecessarily
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other options exist
            score += 150.0 + (100.0 * (1.0 - progress));
        }
    } else {
        // If this is the last chance to fit the item in an existing bin, favor it
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // Lookahead heuristic: If the next item exists, penalize leaving a residual
        // that is too small to accommodate the next item (Dead space avoidance)
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += 40.0;
