                    score -= 30.0;
                }
            }
        }

        // Global state awareness: If the bin is becoming too empty compared to mean,
        // penalize placing items that waste its potential capacity
        if (bin_residual as f64) < mean_residual * 0.5 {
            score += 10.0;
        }
    }

    // Progression scaling: As we approach the end of the stream, 
    // become more aggressive about filling existing bins to minimize new bin creation
    score -= (progress * 20.0);

