}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    // We penalize small residuals (dead space) more heavily as the stream progresses,
    // encouraging tighter packing in the early stages and "Best Fit" in later stages.

    // Penalty for leaving a gap that is too small to fit any likely item (e.g., < 10)
    // or too large to be useful.
    let dead_space_penalty = if post < 10.0 && post > 0.0 {
        20.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin heavily.
    let lookahead_reward = if next_item_size > 0 && (post_residual >= next_item_size) {
        -30.0 * (1.0 - progress)
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), we add a high cost 
    // to discourage opening new bins unless necessary (fitting_bins_count == 0).
    let new_bin_cost = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            0.0 // Necessary
        } else {
            50.0 + (progress * 50.0) // Increase cost as stream progresses
        }
    } else {
        0.0
    };

    // Non-linear coupling: Favor bins that align with the global mean residual
    // to keep bin fill-levels uniform.
    let uniformity_penalty = (post - mean_residual).abs() * 0.5;

    post + dead_space_penalty + lookahead_reward + new_bin_cost + uniformity_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Harmonic-inspired residual optimization.
    // We prioritize keeping the post_residual as small as possible (Best Fit),
    // but penalize creating "fragmentation" (residuals that are too small to fit common items).
    // The "Dead Zone" is defined as residuals < 10, as items are >= 10.

    let mut score = post_residual as f64;

    // Penalty for creating a "dead" residual (0 < x < 10) that can't fit any future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // If this is the last chance to fit the item (fitting_bins_count == 1), 
