    }

    // Lookahead: If the next item fits into the current post_residual, reward this placement.
    // This effectively implements a Best-Fit-Lookahead strategy.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Harmonic load balancing: If the residual is close to a fraction of the capacity,
    // it likely creates better packing density for future items.
    // We favor residuals that are multiples of 25 (1/4th capacity).
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // Penalty for opening a new bin: Only open a new bin if the current fit is extremely poor
    // (e.g., leaving a very large residual that doesn't fit the next item).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other options exist.
            score += 60.0;
        } else {
            // If no other options, normalize the cost of opening a new bin.
            score = 20.0;
        }
    }

    // Progression scaling: As we approach the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
