    let fit_efficiency = if post < 10.0 {
        post * 5.0 // Heavy penalty for creating unusable slivers
    } else if next_item_size > 0 && post >= next_item_size as f64 {
        (post - next_item_size as f64).powi(2) * 0.1
    } else {
        post
    };

    // Factor in the global state: if we have few fitting bins, be more conservative
    // Use a non-linear coupling with progress to transition from aggressive packing (early)
    // to space-filling optimization (late).
    let scarcity_penalty = if fitting_bins_count == 1 {
