    let base_score = if bin_residual == bin_capacity {
        // As stream progresses, make opening new bins increasingly expensive
        // unless the mean_residual is very low (meaning we have no good space).
        (100.0 - mean_residual) + (progress * 50.0)
    } else {
        fit_efficiency + scarcity_penalty
    };

    base_score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
