        }
    }

    // 4. Residual Variance Dampening:
    // Penalize bins that deviate from the mean residual, but tighten the variance tolerance
    // as the stream progresses to force tighter packing towards the end.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * (0.15 + (0.25 * progress));

    // 5. Fragmentation Avoidance:
    // Favor bins that have already been partially filled to keep the open_bins_count low.
    if bin_residual < bin_capacity {
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

