    // Archetype #434: Dynamic Best-Fit with Adaptive Lookahead Penalty (BALP).

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base Score: Focus on Best-Fit (minimizing post_residual).
    // We prefer bins where post_residual is small (tight fit).
    let mut score = post_residual as f64;

    // 2. Penalty for creating unusable gaps:
    // If the post_residual is small but large enough to be "wasted" (e.g., < 10), 
    // it's often worse than a slightly larger residual that might fit a future item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 3. Lookahead Logic:
    // If we have a next item, penalize bins that cannot fit the next item 
    // if this bin is currently the only one that can fit the current item.
    if next_item_size > 0 && fitting_bins_count == 1 && !is_new_bin {
        if post_residual < next_item_size {
            score += 40.0 * (1.0 - progress); 
        }
    }

    // 4. Global State Awareness:
    // If the mean residual is high, we are being too sparse; prioritize filling existing bins.
    // If mean_residual is low, we are tight; be more willing to open a new bin.
    if is_new_bin {
        // High penalty for opening a new bin if we have plenty of space on average.
        score += (mean_residual * 0.5) + (open_bins_count as f64 * 2.0);
    } else {
        // Reward filling existing bins if mean_residual is high.
        score -= mean_residual * 0.2;
    }

    // 5. Progression Scaling:
    // Toward the end of the stream, prioritize closing bins (lower score for filling existing).
    if progress > 0.8 && !is_new_bin {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: Favor filling to completion (minimize post_residual).
    // Increased power to force aggressive compaction of small residuals.
    let mut score = (post_residual as f64).powf(1.31);

    // 1. Refined Fragmentation Mitigation:
    // Penalize the "dead zone" (1-18 range) more aggressively to prevent stranded capacity.
    if post_residual > 0 && post_residual < 19 {
        score += 245.0 * (1.0 - progress * 0.08);
    }

    // 2. Lookahead Synergy (Enhanced):
    // Prioritize bins that accommodate next_item_size with minimal slack.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact fit (zero slack) more heavily.
            let slack = post_residual - next_item_size;
            score -= 310.0 + (1.0 / (slack + 1) as f64) * 210.0;
        } else if post_residual > 0 && post_residual < 24 {
            // Penalty for stranding an item that could have fit elsewhere.
            score += 210.0 * (next_item_size as f64 / 100.0);
        }
    }

    // 3. Adaptive Bin-Opening:
    // Exponentially weight the cost of a new bin based on global packing density.
    if is_new_bin {
        let density_weight = (open_bins_count as f64).powf(1.48) * 16.2;
        let penalty = 420.0 + density_weight;
        // If we have many fitting options, opening a new bin is very expensive.
        score += if fitting_bins_count > 0 { penalty * 8.2 } else { penalty * 0.05 };
    } else {
        // 4. Fitting Scarcity:
        // Prioritize existing bins when the supply of fit-able containers is low.
        if fitting_bins_count < 5 {
            score -= 280.0 / (fitting_bins_count as f64 + 0.25);
        }
    }

    // 5. Mean Residual Alignment:
    // Penalize high variance from the mean to promote uniform bin usage.
    // Adjusted coefficient to penalize deviation from the mean_residual more strictly.
    score += (post_residual as f64 - mean_residual).abs() * 1.15;

    // 6. Tightness/Completion Reward:
    if post_residual == 0 {
        score -= 720.0;
    } else if post_residual < 5 {
        score -= 210.0;
    }

    // 7. Late-stage Compaction:
    // Aggressive consolidation as the stream ends.
    // Use non-linear scaling for late-stage filling to minimize final bin count.
    if progress > 0.85 {
        score -= (bin_capacity - post_residual) as f64 * 9.5;
    } else if progress > 0.6 {
        score -= (bin_capacity - post_residual) as f64 * 2.4;
    }

    score
}

